import { readFile, writeFile } from "node:fs/promises";

const GENERATOR_DIRECTIVE =
  /^\s*(?:\/\/\s*@ts-nocheck\b.*|\/\*\s*(?:eslint-disable(?:\s+[^*]*)?|prettier-ignore)\s*\*\/|\/\/\s*(?:eslint|prettier|biome)-disable\b.*)\r?\n?/gmu;

const GENERATED_TYPECHECK_OPT_OUT =
  "// @ts-nocheck -- generated by @napi-rs/cli";
const ARTIFACT_METADATA_PREFIX = "// napi-rs-artifact-metadata:";
const GENERATED_WASI_WORKER_FACTORY = `function __createWasiWorker(filename) {
  let __workerExecArgv = __getWasiWorkerExecArgv()
  while (true) {
    try {
      return new Worker(filename, {
        env: process.env,
        execArgv: __workerExecArgv,
        workerData: {
          hostRoot: __hostRoot,
          rootDir: __rootDir,
          crashFlag: __wasiThreadCrashFlag,
          crashReport: __wasiThreadCrashReport,
          addonCrashFlag: __wasiAddonCrashFlag,
        },
      })
    } catch (error) {
      if (!error || error.code !== 'ERR_WORKER_INVALID_EXEC_ARGV') {
        throw error
      }
      const __nextWorkerExecArgv =
        __removeInvalidWasiWorkerExecArgv(__workerExecArgv, error)
      if (!__nextWorkerExecArgv) {
        throw error
      }
      __workerExecArgv = __nextWorkerExecArgv
    }
  }
}`;
const NORMALIZED_WASI_WORKER_FACTORY = `function __createWasiWorker(filename) {
  const __workerData = {
    hostRoot: __hostRoot,
    rootDir: __rootDir,
    crashFlag: __wasiThreadCrashFlag,
    crashReport: __wasiThreadCrashReport,
    addonCrashFlag: __wasiAddonCrashFlag,
  }
  const __workerOptions = {
    env: process.env,
    execArgv: __getWasiWorkerExecArgv(),
    workerData: __workerData,
  }
  while (true) {
    try {
      return new Worker(filename, __workerOptions)
    } catch (error) {
      if (!error || error.code !== 'ERR_WORKER_INVALID_EXEC_ARGV') {
        throw error
      }
      const __nextWorkerExecArgv = __removeInvalidWasiWorkerExecArgv(
        __workerOptions.execArgv,
        error,
      )
      if (!__nextWorkerExecArgv) {
        throw error
      }
      __workerOptions.execArgv = __nextWorkerExecArgv
    }
  }
}`;
const GENERATED_BROWSER_WORKER = `const worker = new Worker(new URL('./wasi-worker-browser.mjs', import.meta.url), {
        type: 'module',
      })`;

const NORMALIZED_BROWSER_WORKER = `const __workerData = {
        addonCrashFlag: __wasiAddonCrashFlag,
      }
      const __workerOptions = {
        type: 'module',
        workerData: __workerData,
      }
      const worker = new Worker(
        new URL('./wasi-worker-browser.mjs', import.meta.url),
        __workerOptions,
      )`;
const SAFE_SCHEDULER_HELPER = `function __invokeWasmCleanupPollScheduler(schedule, settle, reject) {
  let finishedDuringScheduling = false
  let scheduling = true
  const finish = () => {
    if (scheduling) {
      finishedDuringScheduling = true
      return
    }
    settle()
  }
  try {
    schedule(finish)
  } catch (error) {
    reject(error)
    return
  }
  scheduling = false
  if (finishedDuringScheduling) {
    settle()
  }
}

`;
const RUNTIME_POLL_MARKER = "/**\n * One turn of the runtime-work poll.";
const UNSAFE_CLEANUP_HANDSHAKE = `await new Promise((resolve) => {
        __scheduleMacrotask(resolve)
      })`;
const SAFE_CLEANUP_HANDSHAKE = `await new Promise((resolve, reject) => {
        __invokeWasmCleanupPollScheduler(
          __scheduleMacrotask,
          resolve,
          reject,
        )
      })`;
const UNSAFE_RUNTIME_POLL_PROMISE = `return new Promise((resolve) => {
    let settled = false`;
const SAFE_RUNTIME_POLL_PROMISE = `return new Promise((resolve, reject) => {
    let settled = false`;
const UNSAFE_RUNTIME_POLL_TIMER = `__scheduleTimer(() => {
      pace.arrivals++
      settle()
    }, __WASM_RUNTIME_WORK_POLL_INTERVAL_MS)`;
const SAFE_RUNTIME_POLL_TIMER = `__invokeWasmCleanupPollScheduler(
      (finish) => {
        __scheduleTimer(() => {
          pace.arrivals++
          finish()
        }, __WASM_RUNTIME_WORK_POLL_INTERVAL_MS)
      },
      settle,
      reject,
    )`;
const UNSAFE_RUNTIME_POLL_MACROTASK = `if (pace.arrivals < __WASM_RUNTIME_WORK_POLL_TRUSTED_ARRIVALS) {
      __scheduleMacrotask(settle)
      return
    }`;
const SAFE_RUNTIME_POLL_MACROTASK = `if (pace.arrivals < __WASM_RUNTIME_WORK_POLL_TRUSTED_ARRIVALS) {
      __invokeWasmCleanupPollScheduler(
        __scheduleMacrotask,
        settle,
        reject,
      )
      return
    }`;
const UNSAFE_ASYNC_WORK_POLL = `await new Promise((resolve) => {
          __scheduleTimer(resolve, __WASI_ASYNC_WORK_POLL_INTERVAL_MS)
        })`;
const SAFE_ASYNC_WORK_POLL = `await new Promise((resolve, reject) => {
          __invokeWasmCleanupPollScheduler(
            (finish) => {
              __scheduleTimer(finish, __WASI_ASYNC_WORK_POLL_INTERVAL_MS)
            },
            resolve,
            reject,
          )
        })`;
const RETRYABLE_RUNTIME_CLEANUP =
  /\}\)\(\)\.then\((finishCleanup(?:UnlessCrashed)?), \1\)/gu;
const makeRuntimeCleanupRetryable = (
  _match: string,
  finishCleanup: string,
) => `})().then(
    ${finishCleanup},
    (error) => {
      __emnapiWasmEnvCleanupPreparing = false
      throw error
    },
  )`;
type Transformation = {
  name: string;
  generated: string;
  normalized: string;
};

const applyTransformation = (
  source: string,
  { name, generated, normalized }: Transformation,
  file: string,
) => {
  if (source.includes(generated))
    return source.replaceAll(generated, normalized);
  if (source.includes(normalized)) return source;
  throw new Error(`WASI loader transformation "${name}" did not match ${file}`);
};
const addTypecheckHeader = (source: string) => {
  if (!source.startsWith(ARTIFACT_METADATA_PREFIX)) {
    return `${GENERATED_TYPECHECK_OPT_OUT}\n${source}`;
  }
  const lineEnd = source.indexOf("\n");
  if (lineEnd < 0) {
    return `${source}\n${GENERATED_TYPECHECK_OPT_OUT}\n`;
  }
  return `${source.slice(0, lineEnd + 1)}${GENERATED_TYPECHECK_OPT_OUT}\n${source.slice(lineEnd + 1)}`;
};
/** Preserve generated scheduling and add only retry and crash-reporting guards. */
export const normalizeGeneratedLoader = (
  source: string,
  {
    keepGeneratedTypecheckOptOut = false,
    file = "<input>",
  }: {
    keepGeneratedTypecheckOptOut?: boolean;
    file?: string;
  } = {},
) => {
  if (source.includes("\r\n"))
    throw new Error(
      `WASI loader transformation "LF line endings" did not match ${file}`,
    );

  let normalized = source.replace(GENERATOR_DIRECTIVE, "");
  const transformations = [
    {
      name: "cleanup handshake",
      generated: UNSAFE_CLEANUP_HANDSHAKE,
      normalized: SAFE_CLEANUP_HANDSHAKE,
    },
    {
      name: "runtime poll promise",
      generated: UNSAFE_RUNTIME_POLL_PROMISE,
      normalized: SAFE_RUNTIME_POLL_PROMISE,
    },
    {
      name: "runtime poll timer",
      generated: UNSAFE_RUNTIME_POLL_TIMER,
      normalized: SAFE_RUNTIME_POLL_TIMER,
    },
    {
      name: "runtime poll macrotask",
      generated: UNSAFE_RUNTIME_POLL_MACROTASK,
      normalized: SAFE_RUNTIME_POLL_MACROTASK,
    },
    {
      name: "async work poll",
      generated: UNSAFE_ASYNC_WORK_POLL,
      normalized: SAFE_ASYNC_WORK_POLL,
    },
  ] satisfies Transformation[];
  for (const transformation of transformations)
    normalized = applyTransformation(normalized, transformation, file);

  if (normalized.match(RETRYABLE_RUNTIME_CLEANUP)) {
    normalized = normalized.replace(
      RETRYABLE_RUNTIME_CLEANUP,
      makeRuntimeCleanupRetryable,
    );
  } else if (!normalized.includes("__emnapiWasmEnvCleanupPreparing = false")) {
    throw new Error(
      `WASI loader transformation "retryable runtime cleanup" did not match ${file}`,
    );
  }

  const workerTransformations = [
    {
      name: "WASI worker factory",
      generated: GENERATED_WASI_WORKER_FACTORY,
      normalized: NORMALIZED_WASI_WORKER_FACTORY,
    },
    {
      name: "browser worker",
      generated: GENERATED_BROWSER_WORKER,
      normalized: NORMALIZED_BROWSER_WORKER,
    },
  ] satisfies Transformation[];
  const workerTransformation = workerTransformations.find(
    ({ generated, normalized: output }) =>
      normalized.includes(generated) || normalized.includes(output),
  );
  if (!workerTransformation)
    throw new Error(
      `WASI loader transformation "worker construction" did not match ${file}`,
    );
  normalized = applyTransformation(normalized, workerTransformation, file);

  normalized = normalized.replace(/[ \t]+$/gmu, "");
  const withSchedulerHelper = normalized.includes(SAFE_SCHEDULER_HELPER)
    ? normalized
    : applyTransformation(
        normalized,
        {
          name: "scheduler helper",
          generated: RUNTIME_POLL_MARKER,
          normalized: `${SAFE_SCHEDULER_HELPER}${RUNTIME_POLL_MARKER}`,
        },
        file,
      );

  return keepGeneratedTypecheckOptOut
    ? addTypecheckHeader(withSchedulerHelper)
    : withSchedulerHelper;
};

const usage =
  "Usage: stll-normalize-wasi-loaders [--check] <browser-loader> <commonjs-loader>";

export const runWasiLoaderNormalizer = async (args: string[]) => {
  const check = args.at(0) === "--check";
  const paths = check ? args.slice(1) : args;
  if (paths.length !== 2 || paths.some((path) => path.startsWith("--")))
    throw new Error(usage);

  let drifted = false;
  for (const path of paths) {
    const source = await readFile(path, "utf8");
    const normalized = normalizeGeneratedLoader(source, {
      keepGeneratedTypecheckOptOut: true,
      file: path,
    });
    if (source === normalized) continue;
    if (check) {
      process.stderr.write(`${path} is not normalized\n`);
      drifted = true;
      continue;
    }
    await writeFile(path, normalized);
  }
  if (drifted) throw new Error("generated WASI loaders have drifted");
};
